Build Hyperframes HTML.kod:
var ad=$("Audio Decode").item.json;
var ev=$("Extract Video URL").item.json;
var videoUrl=ev.videoUrl||"";
var duration=Math.round((ev.duration||60)*100)/100;
var aspect=ad.aspect||"9:16";
var isV=(aspect==="9:16");
var sceneBlocks=ad.sceneBlocks||[];
var alignment=ad.alignment||{characters:[],character_end_times_seconds:[]};

// Compute subtitle blocks from alignment
var MAXCH=70;
var subtitleHtml="";
if(alignment.characters&&alignment.characters.length>0){
  var chars=alignment.characters;
  var endT=alignment.character_end_times_seconds||[];
  var startT=alignment.character_start_times_seconds||[];
  var blocks=[];var cur="";var blockStart=0;
  for(var i=0;i<chars.length;i++){
    cur+=chars[i];
    if(cur.length>=MAXCH||(chars[i]===" "&&cur.length>MAXCH/2)){
      var es=endT[i]||0;
      if(blocks.length>0){var prev=blocks[blocks.length-1];var gap=blockStart-(prev.start+prev.duration);if(gap<0.08)blockStart=prev.start+prev.duration+0.08;}
      blocks.push({text:cur.trim(),start:blockStart,duration:Math.max(0.5,(es-blockStart))});
      cur="";blockStart=endT[i]||0;
    }
  }
  if(cur.trim()){
    var lastT=endT[chars.length-1]||blockStart+1;
    blocks.push({text:cur.trim(),start:blockStart,duration:Math.max(0.5,lastT-blockStart)});
  }
  subtitleHtml=blocks.map(function(b,idx){
    return "<div class=\"clip subtitle-block\" data-start=\""+b.start+"\" data-duration=\""+b.duration+"\" data-track-index=\""+(60+idx)+"\">"+(b.text.replace(/&/g,"&amp;").replace(/</g,"&lt;"))+"</div>";
  }).join("");
}

// Scene blocks HTML
var scHtml="";var scCss="<style>.scene-wrap{position:absolute;top:12%;left:10%;width:80%;opacity:0;}.scene-num{font-family:Inter,sans-serif;font-size:"+(isV?"7vw":"5vw")+";font-weight:700;text-align:center;}.scene-lbl{font-family:Inter,sans-serif;font-size:"+(isV?"2.5vw":"1.8vw")+";font-weight:600;color:#F7F5F0;text-align:center;margin-bottom:1vw;}</style>";
var sceneEsc=function(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;");};
var sceneCol=function(c){return c==="clay"?"#E0584A":(c==="sage"?"#82BD8F":"#D6AD62");};
for(var si=0;si<sceneBlocks.length;si++){
  var sb=sceneBlocks[si];var p=sb.params||{};var id="sc"+si;var col=sceneCol(p.color);
  var st=sb.start||0;var du=sb.duration||3;var fi=Math.min(0.4,du/4);var fo=Math.min(0.4,du/4);var trk=80+si;
  scHtml+="<div id=\""+id+"\" class=\"clip scene-wrap\" data-start=\""+st+"\" data-duration=\""+du+"\" data-track-index=\""+trk+"\">"+(p.label?"<div class=\"scene-lbl\">"+sceneEsc(p.label)+"</div>":"");
  if(sb.type==="count-up"||sb.type==="percent-bar"){
    scHtml+="<div id=\""+id+"n\" class=\"scene-num\" style=\"color:"+col+"\">0</div>";
  }else{
    scHtml+="<div class=\"scene-num\" style=\"color:"+col+"\">"+sceneEsc(p.matn||p.text||"")+"</div>";
  }
  scHtml+="</div>";
}

var ww=isV?1080:1920;var wh=isV?1920:1080;
var subStyle=isV
  ? "bottom:500px;left:60px;right:60px;font-size:70px;"
  : "bottom:120px;left:80px;right:80px;font-size:52px;";

var html="<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Inter:wght@600;800&display=swap\"><style>*{margin:0;padding:0;box-sizing:border-box;}html,body{width:"+ww+"px;height:"+wh+"px;overflow:hidden;background:transparent;}#avatar-video{position:absolute;left:0;top:0;width:"+ww+"px;height:"+wh+"px;object-fit:cover;}.subtitle-block{position:absolute;"+subStyle+"text-align:center;font-family:Inter,system-ui,sans-serif;font-weight:600;color:#F7F5F0;line-height:1.25;background:none;text-shadow:0 2px 12px rgba(10,23,39,.90);paint-order:stroke fill;}.source-label{position:absolute;top:"+(isV?"6.5%":"4%")+";left:50%;transform:translateX(-50%);font-family:Inter,sans-serif;font-weight:600;font-size:"+(isV?"26px":"22px")+";color:rgba(247,245,240,.72);white-space:nowrap;z-index:40;}</style></head><body><div id=\"root\" data-composition-id=\"main\" data-start=\"0\" data-duration=\""+duration+"\" data-width=\""+ww+"\" data-height=\""+wh+"\"><video id=\"avatar-video\" class=\"clip\" src=\""+videoUrl+"\" data-start=\"0\" data-duration=\""+duration+"\" data-track-index=\"0\" playsinline></video>"+subtitleHtml+scCss+scHtml+"</div></body></html>";

// base64 encode
var b64=Buffer.from(html,"utf8").toString("base64");
return{json:{htmlBase64:b64,videoUrl:videoUrl,duration:duration,aspect:aspect,job_id:ad.job_id,jami_s:ad.jami_s,hook_tugash_s:ad.hook_tugash_s,heygen_video_id:ev.heygen_video_id}};

